partial class Shelf {
 Viewbox modalViewport;StackPanel modalBody;Border pendingModalFit;
 void QueueModalFit(){var card=modalCard;if(card==null||pendingModalFit==card)return;pendingModalFit=card;Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,new Action(()=>{if(modalCard!=card||modal=="")return;pendingModalFit=null;FitModal();overlay.UpdateLayout();if(card.Opacity==0)Animate(card,OpacityProperty,new DoubleAnimation(0,1,TimeSpan.FromMilliseconds(120)));}));}

 void FitModal(){if(modalViewport==null||modalCard==null||modalBody==null||modal=="")return;double availableWidth=Math.Max(120,ActualWidth-32),availableHeight=Math.Max(120,ActualHeight-32);modalViewport.MaxWidth=availableWidth;modalViewport.MaxHeight=availableHeight;SetModalDensity(false);modalCard.Measure(new Size(modalCard.Width,double.PositiveInfinity));if(modalCard.DesiredSize.Height>availableHeight)SetModalDensity(true);}
 void SetModalDensity(bool compact){modalBody.Margin=new Thickness(compact?20:26);modalList.Margin=new Thickness(0,compact?12:22,0,0);foreach(var button in modalButtons.Where(b=>b.Resources.Contains("ActionColor"))){button.MinHeight=compact?48:62;button.Margin=new Thickness(0,0,0,compact?4:7);var content=button.Content as Grid;if(content!=null)content.Margin=new Thickness(compact?12:14,compact?5:10,compact?12:14,compact?5:10);}foreach(var label in modalList.Children.OfType<TextBlock>())label.Margin=new Thickness(7,compact?7:12,0,compact?5:10);}

 void NewModal(string type,string title,string subtitle,double width=440){modal=type;overlay.Children.Clear();overlay.Visibility=Visibility.Visible;modalButtons.Clear();modalSelected=0;var body=new StackPanel{Margin=new Thickness(26)};modalBody=body;var head=new Grid();head.ColumnDefinitions.Add(new ColumnDefinition());head.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var text=new StackPanel();var h=Label(title,24,"Fg");h.FontWeight=FontWeights.Bold;h.TextTrimming=TextTrimming.CharacterEllipsis;text.Children.Add(h);var sub=Label(subtitle,11,"Muted");sub.TextWrapping=TextWrapping.Wrap;sub.Margin=new Thickness(0,6,0,0);text.Children.Add(sub);head.Children.Add(text);var close=IconButton("close","关闭 · B / ○ / Esc",CloseModal,34);Grid.SetColumn(close,1);head.Children.Add(close);body.Children.Add(head);modalList=new StackPanel{Margin=new Thickness(0,22,0,0)};body.Children.Add(modalList);modalCard=Box(body,"Surface",24);modalCard.Width=width;modalCard.HorizontalAlignment=HorizontalAlignment.Center;modalCard.VerticalAlignment=VerticalAlignment.Center;modalCard.BorderThickness=new Thickness(1);modalCard.SetResourceReference(Border.BorderBrushProperty,"Line");modalCard.Effect=new DropShadowEffect{BlurRadius=70,Opacity=.5,ShadowDepth=20};modalViewport=new Viewbox{Child=modalCard,Stretch=Stretch.Uniform,StretchDirection=StretchDirection.DownOnly,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};overlay.Children.Add(modalViewport);modalCard.Opacity=0;QueueModalFit();main.Focus();DrawHints();}
 void ModalRow(string icon,string title,string detail,Action action,bool chosen=false){var g=new Grid{Margin=new Thickness(14,10,14,10)};g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(34)});g.ColumnDefinitions.Add(new ColumnDefinition());g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(24)});var symbol=Glyph(icon,19);symbol.HorizontalAlignment=HorizontalAlignment.Left;g.Children.Add(symbol);var t=new StackPanel();t.Children.Add(Label(title,14,"Fg"));if(!string.IsNullOrEmpty(detail)){var sub=Label(detail,10,"Muted");sub.TextTrimming=TextTrimming.CharacterEllipsis;sub.Margin=new Thickness(0,3,0,0);t.Children.Add(sub);}Grid.SetColumn(t,1);g.Children.Add(t);if(chosen){var check=Glyph("check",16);Grid.SetColumn(check,2);g.Children.Add(check);}var b=new Button{Content=g,HorizontalContentAlignment=HorizontalAlignment.Stretch,Margin=new Thickness(0,0,0,7),ToolTip=title,MinHeight=50};b.Click+=(o,e)=>action();int index=modalButtons.Count;b.MouseEnter+=(o,e)=>{if(!controllerNavigation){if(modalSelected!=index)PlayUi("move");modalSelected=index;MarkModal();}};{string accent=ActionColor(icon);b.Resources["ActionColor"]=accent;((System.Windows.Shapes.Path)symbol).Stroke=B(accent);g.ColumnDefinitions[0].Width=new GridLength(48);g.Children.Remove(symbol);var badge=new Border{Child=symbol,Width=35,Height=35,CornerRadius=new CornerRadius(10),Background=Tint(accent,dark?(byte)25:(byte)18),HorizontalAlignment=HorizontalAlignment.Left};symbol.HorizontalAlignment=HorizontalAlignment.Center;g.Children.Add(badge);b.MinHeight=62;b.ToolTip=null;b.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Border Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1' CornerRadius='14'><ContentPresenter VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsPressed' Value='True'><Setter Property='Opacity' Value='.7'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");}modalButtons.Add(b);modalList.Children.Add(b);MarkModal();QueueModalFit();}
 void ModalLabel(string text){var t=Label(text,10,"Muted");t.Margin=new Thickness(7,12,0,10);modalList.Children.Add(t);QueueModalFit();}
 string MenuAccent(int index){string[] colors={"#46DDB6","#F18DBD","#EDBF69","#65BEF5","#AA91FF","#739FFF","#F08B93"};return modal=="game"?colors[index%colors.Length]:Accent;}
 void MarkModal(){for(int i=0;i<modalButtons.Count;i++){var b=modalButtons[i];bool active=i==modalSelected;string accent=b.Resources["ActionColor"] as string??MenuAccent(i);if(b.Resources.Contains("ActionColor")){var color=(Color)ColorConverter.ConvertFromString(accent);b.Background=active?(Brush)new LinearGradientBrush(Color.FromArgb(dark?(byte)55:(byte)35,color.R,color.G,color.B),Color.FromArgb(6,color.R,color.G,color.B),0):Brushes.Transparent;b.BorderBrush=active?B(accent):Brushes.Transparent;}else{b.SetResourceReference(Control.BackgroundProperty,active?"AccentSoft":"Surface");b.BorderBrush=active?B(Accent):Brushes.Transparent;}b.BorderThickness=new Thickness(1);}}
 void MoveModal(int delta){if(modalButtons.Count==0)return;modalSelected=(modalSelected+delta+modalButtons.Count)%modalButtons.Count;MarkModal();modalButtons[modalSelected].BringIntoView();}
 void Confirm(){if(launching)return;PlayUi("confirm");if(modal!=""){if(modalButtons.Count>modalSelected)modalButtons[modalSelected].RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}else ActivateNavigation();}
 void CloseModal(){if(launching)return;modal="";menuGame=null;overlay.Visibility=Visibility.Collapsed;overlay.Children.Clear();modalViewport=null;modalBody=null;modalButtons.Clear();DrawHints();main.Focus();RefreshNavFocus();}
 void OpenGame(Game g){if(launching)return;PlayUi("confirm");menuGame=g;NewModal("game",g.Name,"游戏操作 · 方向键选择，确认执行",460);ModalRow("play","启动游戏","进入游戏世界",()=>Launch(g));ModalRow("heart",State(g).Favorite?"取消收藏":"添加收藏","在收藏游戏中快速找到",()=>{State(g).Favorite=!State(g).Favorite;PlayUi(State(g).Favorite?"favorite":"remove");Save();Render(g.Path);OpenGame(g);},State(g).Favorite);ModalRow("folder","打开游戏文件夹","定位到游戏启动文件所在目录",()=>OpenGameFolder(g));ModalRow("play","选择启动文件","识别不准确时手动指定游戏 EXE",()=>ChooseGameEntry(g));ModalRow("refresh","更新封面","重新在线获取游戏图片",()=>RefreshCover(g));ModalRow("image","选择本地封面","使用你自己的游戏图片",()=>ChooseCover(g));ModalRow("link","指定 Steam 游戏","使用商店链接或 App ID 匹配",()=>ChooseId(g));ModalRow(State(g).Hidden?"eye":"hide",State(g).Hidden?"恢复游戏":"移除游戏",State(g).Hidden?"重新显示在游戏库":"仅从游戏库隐藏，保留游戏及快捷方式",()=>{State(g).Hidden=!State(g).Hidden;PlayUi(State(g).Hidden?"remove":"switch");Save();CloseModal();Render();});}
 void OpenSettings(){if(launching)return;PlayUi("switch");NewModal("settings","设置","精简游戏库 · 所有设置自动保存",470);ModalLabel("游戏库");ModalRow("folder","游戏扫描目录",LibraryFolders().Length+" 个目录 · 直接识别安装文件",OpenFolders);ModalRow("folder","打开游戏文件夹","在资源管理器中查看",()=>{try{Process.Start("explorer.exe",folder);}catch(Exception ex){status.Text=ex.Message;}});ModalRow("hide","已移除游戏",games.Count(g=>State(g).Hidden)+" 款 · 可恢复显示",()=>{filter="hidden";CloseModal();selected=0;Render();});ModalLabel("外观与显示");ModalRow(theme=="浅色"?"sun":theme=="深色"?"moon":"monitor","主题",theme,OpenThemes);ModalRow("monitor","默认启动方式",options.StartupMode=="全屏"?"全屏":"窗口",OpenStartupMode);ModalLabel("全屏布局：每行 9 张 · 动画目标：144 帧/秒");ModalRow(fullscreen?"restore":"full",fullscreen?"退出全屏":"进入全屏","快捷键 F11",()=>{ToggleFull();OpenSettings();});ModalLabel("应用");ModalRow("pad","界面音效",options.SoundEnabled?"已开启 · "+options.SoundStyle:"已关闭",OpenAudio);ModalRow("exit","退出软件","关闭 GAMES，不影响正在运行的游戏",()=>Close());}
 string GameDirectory(Game g){var target=ResolveLaunch(new Game{Path=EffectiveEntry(g),Name=g.Name,OriginalName=g.OriginalName},false);return !string.IsNullOrWhiteSpace(target.Directory)&&Directory.Exists(target.Directory)?target.Directory:null;}
 void OpenGameFolder(Game g){try{string directory=GameDirectory(g);if(directory==null){status.Text="无法定位游戏安装目录：请检查快捷方式目标或游戏是否已安装";return;}Process.Start(new ProcessStartInfo("explorer.exe","\""+directory+"\""){UseShellExecute=true});CloseModal();}catch(Exception ex){status.Text="打开游戏目录失败 · "+ex.Message;}}
 bool startupDisplayApplied=false;
 void ApplyStartupDisplay(){if(startupDisplayApplied)return;startupDisplayApplied=true;bool wantFull=options.StartupMode=="全屏";if(fullscreen!=wantFull)ToggleFull();}
 void OpenStartupMode(){NewModal("startup-mode","默认启动方式","保存后下次启动生效");foreach(string mode in new[]{"窗口","全屏"}){string choice=mode;ModalRow(choice=="全屏"?"full":"restore",choice,choice=="全屏"?"启动后进入全屏游戏库":"启动后显示普通窗口",()=>{options.StartupMode=choice;Save();PlayUi("switch");OpenStartupMode();},(options.StartupMode=="全屏"?"全屏":"窗口")==choice);}}
 void OpenThemes(){NewModal("themes","外观主题","选择你喜欢的明暗风格");foreach(string name in new[]{"深色","浅色","跟随系统"}){string n=name;ModalRow(n=="深色"?"moon":n=="浅色"?"sun":"monitor",n,n=="跟随系统"?"自动响应 Windows 应用主题":"",()=>{theme=n;Save();ApplyTheme(true);OpenThemes();},theme==n);}}
 void OpenFilters(){NewModal("filters","筛选游戏","按当前游戏库的状态筛选");foreach(var pair in new[]{new[]{"all","grid","全部游戏"},new[]{"favorite","heart","收藏游戏"},new[]{"recent","clock","最近游玩"},new[]{"unplayed","play","尚未游玩"},new[]{"missing","image","缺少封面"},new[]{"hidden","hide","已移除游戏"}}){string key=pair[0];ModalRow(pair[1],pair[2],"",()=>{PlayUi("switch");filter=key;selected=0;CloseModal();Render();},filter==key);}}
 void OpenSort(){NewModal("sort","排列顺序","排序方式会自动保存");foreach(var pair in new[]{new[]{"name","名称 · 升序"},new[]{"name-desc","名称 · 降序"},new[]{"added","最近添加"},new[]{"played","最近游玩"},new[]{"count","启动次数"}}){string key=pair[0];ModalRow("sort",pair[1],"",()=>{PlayUi("switch");options.Sort=key;Save();selected=0;CloseModal();Render();},options.Sort==key);}}
 void ChooseCover(Game g){var d=new OpenFileDialog{Filter="图片|*.jpg;*.jpeg;*.png;*.bmp",Title="选择游戏封面"};if(d.ShowDialog()==true)try{var bmp=new BitmapImage(new Uri(d.FileName));var enc=new JpegBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(bmp));using(var f=File.Create(g.Cover))enc.Save(f);File.WriteAllText(g.Cover+".manual","1");File.Delete(g.Cover+".fit");CloseModal();Render(g.Path);}catch(Exception ex){status.Text="更换失败 · "+ex.Message;}}
 void ChooseId(Game g){NewModal("appid","指定 Steam 游戏","粘贴商店链接，或输入数字 App ID");var input=new TextBox{Padding=new Thickness(12),Margin=new Thickness(0,0,0,16),FontSize=14};input.SetResourceReference(Control.BackgroundProperty,"Track");input.SetResourceReference(Control.ForegroundProperty,"Fg");modalList.Children.Add(input);ModalRow("check","保存并更新","",()=>{var m=System.Text.RegularExpressions.Regex.Match(input.Text.Trim(),@"^(?:https?://store\.steampowered\.com/app/)?(\d+)(?:/.*)?$");if(!m.Success){status.Text="请输入有效的 Steam 链接或 App ID";return;}File.WriteAllText(g.Cover+".appid",m.Groups[1].Value);RefreshCover(g);});input.Focus();}
